<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Báo cáo sự cố</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="/assets/css/style.css"></head>
<body><div class="app-shell"><?php renderApplicationSidebar($user,'/views/suco/index.php'); ?><main class="main-panel"><header class="topbar"><div><h2>Báo cáo sự cố</h2><p>Gửi sự cố của phòng để chủ trọ tiếp nhận và khắc phục.</p></div><div class="top-actions"><button type="button" class="btn btn-primary" id="newIncident"><i class="bi bi-plus-lg"></i> Báo sự cố</button></div></header><section class="card-panel"><div class="table-responsive"><table class="table table-modern"><thead><tr><th>Tiêu đề</th><th>Phòng</th><th>Ngày báo</th><th>Trạng thái</th></tr></thead><tbody id="incidentBody"></tbody></table></div></section></main></div>
<div class="modal fade" id="incidentModal" tabindex="-1"><div class="modal-dialog"><form class="modal-content" id="incidentForm"><div class="modal-header"><h5 class="modal-title">Báo cáo sự cố</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Tiêu đề</label><input id="incidentTitle" class="form-control mb-3" required><label class="form-label">Mô tả</label><textarea id="incidentContent" class="form-control" rows="5" required></textarea></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Đóng</button><button class="btn btn-primary">Gửi chủ trọ</button></div></form></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="/assets/js/app.js"></script><script>(()=>{const modalElement=document.getElementById('incidentModal'),openButton=document.getElementById('newIncident'),form=document.getElementById('incidentForm'),body=document.getElementById('incidentBody'),title=document.getElementById('incidentTitle'),content=document.getElementById('incidentContent');if(!modalElement||!openButton||!form)return;const modal=bootstrap.Modal.getOrCreateInstance(modalElement);async function load(){const result=await app.api('/api/suco.php');body.innerHTML=(result.data||[]).map(item=>`<tr><td>${item.TieuDe}</td><td>${item.SoPhong||'—'}</td><td>${String(item.NgayTao||'').slice(0,10).split('-').reverse().join('/')}</td><td><span class="badge bg-info">${item.TrangThai}</span></td></tr>`).join('')||'<tr><td colspan="4" class="text-muted text-center">Chưa có sự cố.</td></tr>'}openButton.addEventListener('click',()=>modal.show());form.addEventListener('submit',async event=>{event.preventDefault();await app.api('/api/suco.php',{method:'POST',body:JSON.stringify({TieuDe:title.value,NoiDung:content.value})});modal.hide();form.reset();load()});load()})()</script></body></html>
